INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a3839490-2160-5601-b542-db6f9447a870','TEXT','Proofreading passage PD','The students checked the airflow before the activity began. Our group recorded the airflows in the class notebook. The students checked the airfoil before the activity began. Our group recorded the airfoils in the class notebook. The students checked the airfone before the activity began. Our group recorded the airfones in the class notebook. The students checked the airforce before the activity began. Our group recorded the airforces in the class notebook. The students checked the airframe before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
