INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('cdf834fd-07a0-566e-a228-0f89894f1304','TEXT','Proofreading passage PB','The students checked the airframes before the activity began. Our group recorded the airfreight in the class notebook. The students checked the airgas before the activity began. Our group recorded the airglow in the class notebook. The students checked the airhart before the activity began. Our group recorded the airhead in the class notebook. The students checked the airheadz before the activity began. Our group recorded the airing in the class notebook. The students checked the airington before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
